348	    /**
349	     * Return the Pet with the given name, or null if none found for this Owner.
350	     *
351	     * @param name to test
352	     * @return true if pet name is already in use
353	     */
354	    public Pet getPet(String name, boolean ignoreNew) {
355	        name = name.toLowerCase();
356	        for (Pet pet : getPetsInternal()) {
357	            if (!ignoreNew || !pet.isNew()) {
358	                String compName = pet.getName();
359	                compName = compName.toLowerCase();
360	                if (compName.equals(name)) {
361	                    return pet;
362	                }
363	            }
364	        }
365	        return null;
366	    }
367	
368	    public Pet getPet(Integer petId) {
369	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
370	    }
371	
372	    @Override
373	    public String toString() {
374	        return new ToStringCreator(this)
375	
376	            .append("id", this.getId())
377	            .append("new", this.isNew())
378	            .append("lastName", this.getLastName())
379	            .append("firstName", this.getFirstName())
380	            .append("address", this.address)
381	            .append("city", this.city)
382	            .append("telephone", this.telephone)
383	            .toString();
384	    }
